const adminExportActivityLogs = `-- name: AdminExportActivityLogs :many
SELECT al.id, al.app_id,
       COALESCE(a.name, '') AS app_name,
       al.user_id,
       COALESCE(u.email, '') AS user_email,
       al.event_type, al.severity,
       al.ip_address, al.user_agent,
       al.is_anomaly,
       al.timestamp
FROM activity_logs al
LEFT JOIN users u ON u.id = al.user_id
LEFT JOIN applications a ON a.id = al.app_id
WHERE ($2::text IS NULL OR al.event_type = $2::text)
  AND ($3::text IS NULL OR al.severity = $3::text)
  AND ($4::uuid IS NULL OR al.app_id = $4::uuid)
  AND ($5::text IS NULL OR u.email ILIKE '%' || $5::text || '%')
  AND ($6::timestamptz IS NULL OR al.timestamp >= $6::timestamptz)
  AND ($7::timestamptz IS NULL OR al.timestamp <= $7::timestamptz)
ORDER BY al.timestamp DESC
LIMIT $1
`

